import { describe, expect, test } from "bun:test";
import { greet, add, slugify } from "./utils";

describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });
});

describe("slugify", () => {
  test("converts uppercase to lowercase", () => {
    expect(slugify("UPPERCASE")).toBe("uppercase");
    expect(slugify("MixedCase123")).toBe("mixedcase123");
    expect(slugify("Hello, World!")).toMatch(/^hello/);
  });

  test("replaces spaces with hyphens", () => {
    expect(slugify("Hello World")).toBe("hello-world");
    expect(slugify("one two three")).toBe("one-two-three");
  });

  test("replaces underscores with hyphens", () => {
    expect(slugify("Foo__Bar")).toBe("foo-bar");
    expect(slugify("test_case")).toBe("test-case");
  });

  test("removes invalid characters", () => {
    expect(slugify("Hello, World!")).toBe("hello-world");
    expect(slugify("test@email.com")).toBe("testemailcom");
    expect(slugify("a+b=c")).toBe("abc");
  });

  test("collapses multiple hyphens to single hyphen", () => {
    expect(slugify("a---b")).toBe("a-b");
    expect(slugify("foo--bar")).toBe("foo-bar");
    expect(slugify("test----case")).toBe("test-case");
  });

  test("trims leading and trailing hyphens", () => {
    expect(slugify("-hello-")).toBe("hello");
    expect(slugify("--start")).toBe("start");
    expect(slugify("end--")).toBe("end");
    expect(slugify("-both-")).toBe("both");
  });

  test("handles composite transformations", () => {
    expect(slugify("  Foo__Bar  ")).toBe("foo-bar");
    expect(slugify("Hello, World!")).toBe("hello-world");
    expect(slugify("a---b")).toBe("a-b");
    expect(slugify("!!!@@@###")).toBe("");
  });

  test("handles edge cases", () => {
    expect(slugify("")).toBe("");
    expect(slugify("   ")).toBe("");
    expect(slugify("123")).toBe("123");
    expect(slugify("a")).toBe("a");
  });

  test("handles complex real-world examples", () => {
    expect(slugify("Hello, World! My First Post")).toBe("hello-world-my-first-post");
    expect(slugify("Project #1: Design & Dev!!!")).toBe("project-1-design-dev");
  });
});

