/**
 * Utility functions for the eval test project.
 */

/**
 * Greet someone by name.
 */
export function greet(name: string): string {
  return `Hello, ${name}!`;
}

/**
 * Add two numbers.
 */
export function add(a: number, b: number): number {
  return a + b;
}

/**
 * Convert arbitrary text into URL-friendly slugs.
 *
 * Transforms input by converting to lowercase, replacing spaces and underscores
 * with hyphens, removing invalid characters, collapsing multiple hyphens, and
 * trimming leading/trailing hyphens.
 *
 * @param text - The input string to transform
 * @returns A URL-friendly slug containing only lowercase letters, numbers, and hyphens
 *
 * @example
 * slugify("Hello, World!") // "hello-world"
 * slugify("Project #1: Design & Dev!!!") // "project-1-design-dev"
 */
export function slugify(text: string): string {
  return text
    .toLowerCase()
    .replace(/[\s_]+/g, "-")
    .replace(/[^a-z0-9-]/g, "")
    .replace(/-+/g, "-")
    .replace(/^-+|-+$/g, "");
}

